11	// ============================================================
12	// EmbeddingDenseBackward AscendC Kernel
13	//
14	// 计算 embedding 层反向传播的权重梯度:
15	//   output[num_weights, E] = scatter_add(grad_output[totalN, E], indices[totalN])
16	//
17	// Tiling 策略:
18	//   - Block 级: 沿 E 维度切分到各 Core（无数据竞争）
19	//   - UB 级: 核内沿 E 切片进一步分 tile
20	//   - Phase 1: 散列累加 (scatter-add)
21	//   - SyncAll: 核间同步
22	//   - Phase 2: 频率缩放 + 填充行置零
23	// ============================================================
24	
25	#include "kernel_operator.h"
26	
27	using namespace AscendC;
28	
29	constexpr int64_t BUFFER_NUM = 2;
30	
31	
32	template <typename T>
33	class EmbeddingDenseBackwardKernel {
34	public:
35	    __aicore__ inline EmbeddingDenseBackwardKernel() {}
36	
37	    __aicore__ inline void Init(
38	        GM_ADDR grad, GM_ADDR indices, GM_ADDR output,
39	        GM_ADDR freqWorkspace,
40	        int64_t totalN, int64_t E, int64_t numWeights,
41	        int64_t paddingIdx, int64_t scaleGradByFreq,
42	        int64_t eFormerNum, int64_t eFormerLength,
43	        int64_t eTailNum, int64_t eTailLength,
44	        int64_t eTileLength);
45	
46	    __aicore__ inline void Process();
47	
48	private:
49	    __aicore__ inline void Phase1ScatterAdd(int64_t eTile, int64_t curETile);
50	    __aicore__ inline void Phase1CountFreq(int64_t eTile, int64_t curETile);
51	    __aicore__ inline void Phase2ScaleRows(int64_t eStart, int64_t eSlice);
52	    __aicore__ inline void Phase2ZeroPadding(int64_t eStart, int64_t eSlice);
53	
54	    __aicore__ inline void ScaleRow(int64_t row, int64_t eOffset, int64_t len, float scale);
55	    __aicore__ inline void ZeroRow(int64_t row, int64_t eOffset, int64_t len);
56	
57	private:
58	    TPipe pipe;
59	
60	    TQue<TPosition::VECIN, BUFFER_NUM> inQueue;
61	    TQue<TPosition::VECOUT, BUFFER_NUM> outQueue;
62	    TBuf<TPosition::VECCALC> readBuf;
63	    TBuf<TPosition::VECCALC> fp32GradBuf;
64	    TBuf<TPosition::VECCALC> fp32ExistBuf;
65	    TBuf<TPosition::VECCALC> fp32ResultBuf;
66	
67	    GlobalTensor<T> gradGm;
68	    GlobalTensor<int64_t> indicesGm;
69	    GlobalTensor<T> outputGm;
70	    GlobalTensor<int64_t> freqGm;
71	
72	    int64_t totalN_ = 0;
73	    int64_t E_ = 0;
74	    int64_t numWeights_ = 0;
75	    int64_t paddingIdx_ = 0;
76	    int64_t scaleGradByFreq_ = 0;
77	
78	    int64_t eFormerNum_ = 0;
79	    int64_t eFormerLength_ = 0;
80	    int64_t eTailNum_ = 0;

80	    // ---- Block 级 Tiling: 沿 E 维度切分 ----
81	    int64_t alignCacheElements = CACHE_LINE_BYTES / dtypeSize;
82	    if (alignCacheElements < 1) alignCacheElements = 1;
83	
84	    int64_t totalLengthCore = (E + coreNum - 1) / coreNum;
85	    int64_t totalLengthCoreAlign =
86	        ((totalLengthCore + alignCacheElements - 1) / alignCacheElements) * alignCacheElements;
87	    if (totalLengthCoreAlign < 1) totalLengthCoreAlign = alignCacheElements;
88	
89	    int64_t usedCoreNum = (E + totalLengthCoreAlign - 1) / totalLengthCoreAlign;
90	    if (usedCoreNum < 1) usedCoreNum = 1;
91	    if (usedCoreNum > coreNum) usedCoreNum = coreNum;
92	
93	    int64_t eFormerNum = usedCoreNum - 1;
94	    int64_t eTailNum = 1;
95	    if (eFormerNum < 1) {
96	        eFormerNum = usedCoreNum;
97	        eTailNum = 0;
98	    }
99	    int64_t eFormerLength = totalLengthCoreAlign;
100	    int64_t eTailLength = E - (usedCoreNum - 1) * eFormerLength;
101	    if (eTailLength < 0) eTailLength = 0;
102	
103	    // ---- UB 级 Tiling ----
104	    // bufferCoefficient = 24, UB_SIZE from platform
105	    int64_t maxTileElements = static_cast<int64_t>(ubSizeBytes) /
106	                              (BUFFER_COEFFICIENT * static_cast<int64_t>(sizeof(half)));
107	    if (maxTileElements < 1) maxTileElements = 1;
108	
109	    int64_t alignUbElements = UB_ALIGN_BYTES / dtypeSize;
110	    if (alignUbElements < 1) alignUbElements = 1;
111	
112	    int64_t eTileLength = (maxTileElements / alignUbElements) * alignUbElements;
113	    if (eTileLength < 1) eTileLength = alignUbElements;
114	
115	    // ---- EXEC_KERNEL_CMD (所有参数均为左值) ----
116	    uint32_t blockDim = static_cast<uint32_t>(usedCoreNum);
117	    if (blockDim < 1) blockDim = 1;
118	
