// ============================================================
// index_select Host 端
//
// 3D 布局: [outerSize, srcDimSize, innerSize]
// index 为 1D, 所有 outer 共享
// 动态核分配: 按 index 批次分配核数
// ============================================================

#include "torch_kernel_helper.h"
#include "aclrtlaunch_index_select.h"
#include <torch/extension.h>

namespace ascend_kernel {

constexpr int64_t MAX_CORES = 40;
constexpr int64_t MAX_INDEX_BATCH = 512;

at::Tensor index_select(const at::Tensor& input, int64_t dim, const at::Tensor& index) {
    // ---- 输入校验 ----
    TORCH_CHECK(input.device().type() == at::DeviceType::PrivateUse1,
                "index_select: input must be on NPU device");
    TORCH_CHECK(index.device().type() == at::DeviceType::PrivateUse1,
                "index_select: index must be on NPU device");

    int64_t ndim = input.dim();
    if (dim < 0) dim += ndim;

    TORCH_CHECK(dim >= 0 && dim < ndim,
                "index_select: dim out of range, got dim=", dim);
    TORCH_CHECK(index.dim() == 1,
                "index_select: index must be 1D");

    TORCH_CHECK(input.scalar_type() == at::kFloat ||
                input.scalar_type() == at::kHalf ||
                input.scalar_type() == at::kBFloat16,
                "index_select: only float32, float16 and bfloat16 are supported");

    // ---- 连续化 ----
    at::Tensor inputContiguous = input.contiguous();
    at::Tensor indexContiguous = index.contiguous();

    // ---- 3D 维度参数 ----
    // input:  [outerSize, srcDimSize, innerSize]
    // output: [outerSize, indexSize,  innerSize]
    int64_t outerSize = 1;
    for (int64_t i = 0; i < dim; i++) outerSize *= inputContiguous.size(i);

    int64_t srcDimSize = inputContiguous.size(dim);

    int64_t innerSize = 1;
    for (int64_t i = dim + 1; i < ndim; i++) innerSize *= inputContiguous.size(i);

    int64_t indexSize = indexContiguous.size(0);
    int64_t totalLength = outerSize * indexSize * innerSize;

    // dtypeSize: fp16/bf16=2, fp32=4
    int64_t dtypeSize = static_cast<int64_t>(inputContiguous.element_size());

    // ---- Index int64 → int32 ----
    auto indexInt32 = indexContiguous.to(at::kInt);

    // ---- 输出张量 ----
    auto outputShape = inputContiguous.sizes().vec();
    outputShape[dim] = indexSize;
    auto output = at::empty(outputShape, inputContiguous.options());

    if (totalLength == 0) return output;

    // ---- Block 级 Tiling: 动态核分配 ----
    int64_t indexBatchSize = indexSize < MAX_INDEX_BATCH ? indexSize : MAX_INDEX_BATCH;
    if (indexBatchSize < 1) indexBatchSize = 1;
    int64_t idealCoresPerOuter = (indexSize + indexBatchSize - 1) / indexBatchSize;
    if (idealCoresPerOuter < 1) idealCoresPerOuter = 1;

    int64_t totalTasks = outerSize * idealCoresPerOuter;
    int64_t coresPerOuter;
    uint32_t blockDim;

    if (totalTasks <= MAX_CORES) {
        coresPerOuter = idealCoresPerOuter;
        blockDim = static_cast<uint32_t>(totalTasks);
    } else {
        coresPerOuter = MAX_CORES / outerSize;
        if (coresPerOuter < 1) coresPerOuter = 1;
        blockDim = MAX_CORES;
    }
    if (blockDim < 1) blockDim = 1;

    // EXEC_KERNEL_CMD: 所有参数必须为左值
    // 声明局部变量确保全部为左值
    int64_t outerSizeVal = outerSize;
    int64_t innerSizeVal = innerSize;
    int64_t indexSizeVal = indexSize;
    int64_t srcDimSizeVal = srcDimSize;
    int64_t totalLengthVal = totalLength;
    int64_t coresPerOuterVal = coresPerOuter;
    int64_t dtypeSizeVal = dtypeSize;

    EXEC_KERNEL_CMD(index_select, blockDim, inputContiguous, indexInt32, output,
                    outerSizeVal, innerSizeVal, indexSizeVal, srcDimSizeVal,
                    totalLengthVal, coresPerOuterVal, dtypeSizeVal);

    return output;
}

}  // namespace ascend_kernel
